<?php
$archived=manage()&&($_GET['archivados']??'')==='1';
[$scope,$params]=Access::labScope($archived);
$labs=query('SELECT l.*, (SELECT COUNT(*) FROM equipo e WHERE e.id_laboratorio=l.id_laboratorio AND e.activo=1) equipos FROM laboratorio l WHERE '.$scope.' ORDER BY l.nombre',$params)->fetchAll();
$edit=null;$id=is_string($_GET['edit']??null)?$_GET['edit']:'';
if(manage()&&ctype_digit($id)){$edit=Access::lab($id);}
?>
<div class="page-heading"><div><p class="eyebrow">ORGANIZACIÓN</p><h1><?= manage()?'Laboratorios':'Mi laboratorio actual' ?></h1><p class="muted"><?= manage()?'Administrá espacios y equipos.':'Consultá los equipos y comentá sobre tu laboratorio asignado.' ?></p></div><?php if(manage()): ?><a class="text-link" href="<?= e(url('laboratorios',['archivados'=>$archived?'0':'1'])) ?>"><?= $archived?'Ver activos':'Ver eliminados' ?></a><?php endif ?></div>
<div class="split-layout"><section class="panel"><div class="panel-heading"><h2><?= $archived?'Laboratorios eliminados':'Espacios disponibles' ?></h2></div>
<?php if(!$labs): ?><div class="empty"><h3>No hay laboratorios disponibles</h3><p><?= manage()?'Creá un laboratorio para comenzar.':'El asistente debe asignarte un laboratorio con una vigencia actual.' ?></p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Laboratorio</th><th>PC activas</th><th>Acciones</th></tr></thead><tbody><?php foreach($labs as $lab): ?><tr><td><strong><?= e($lab['nombre']) ?></strong></td><td><?= e($lab['equipos']) ?></td><td class="actions"><?php if(!$archived): ?><a href="<?= e(url('laboratorio',['id'=>$lab['id_laboratorio']])) ?>">Detalle y comentarios</a><a href="<?= e(url('equipos',['lab'=>$lab['id_laboratorio']])) ?>">Ver PC</a><?php endif ?><?php if(manage()): ?><?php if(!$archived): ?><a href="<?= e(url('laboratorios',['edit'=>$lab['id_laboratorio']])) ?>#formulario">Editar</a><?php endif ?><form method="post" action="<?= e(url('laboratorios')) ?>" class="inline-form"><?= csrf() ?><input type="hidden" name="action" value="archive_lab"><input type="hidden" name="id" value="<?= e($lab['id_laboratorio']) ?>"><input type="hidden" name="restore" value="<?= $archived?'1':'0' ?>"><button class="link-button" type="submit"><?= $archived?'Restaurar':'Eliminar (archivar)' ?></button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
<?php if(manage()): ?><section class="panel form-panel" id="formulario"><p class="eyebrow">ADMINISTRACIÓN</p><h2><?= $edit?'Editar laboratorio':'Nuevo laboratorio' ?></h2><form method="post" action="<?= e(url('laboratorios',$edit?['edit'=>$edit['id_laboratorio']]:[])) ?>"><?= csrf() ?><input type="hidden" name="action" value="save_lab"><input type="hidden" name="id" value="<?= e($edit['id_laboratorio']??'') ?>"><label for="nombre">Nombre del laboratorio</label><input id="nombre" name="nombre" maxlength="100" required placeholder="Ej. Laboratorio 6" value="<?= e(input('action')==='save_lab'?input('nombre'):($edit['nombre']??'')) ?>"><button class="button full" type="submit"><?= $edit?'Guardar cambios':'+ Crear laboratorio' ?></button><?php if($edit): ?><a class="cancel" href="<?= e(url('laboratorios')) ?>">Cancelar</a><?php endif ?></form><p class="small muted">Eliminar archiva el laboratorio; los registros históricos se conservan. Primero hay que retirar sus PC activas y asignaciones docentes.</p></section><?php endif ?></div>
